\begin{document}

	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\pagestyle{empty} %% IMPORTANT
	\begin{tikzpicture}

	\begin{axis}[
	legend cell align={left},
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend pos=outer north east,
	legend style={font=\footnotesize},
	tick style={draw=black},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	axis equal,
	%grid = both,
	xmin = -0.2,
	xmax = 1.2,
	ymin = -0.2,
	ymax = 1.2,
	xtick = {1},
	ytick = {0},  
	xlabel = $x$,
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={
		at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

	\draw[dashed, ultra thin] (axis cs:0,0) -- (axis cs:{1.1*cos(deg(pi/6))},{1.1*sin(deg(pi/6))}) 
	node[above right, yshift=-3pt] {\small $\theta = \dfrac{\pi}{6}$};
	\draw[dashed, ultra thin] (axis cs:0,0) -- (axis cs:{0.75*cos(deg(0))},{0.75*sin(deg(0))}) 
	node[above, yshift=2pt] {};

	\begin{scope}
\path[clip] plot[domain=0:180, samples=180] 
			(axis cs: {cos(\x)*cos(\x)}, {cos(\x)*sin(\x)}) 
			-- (current page.north east) 
			-- (current page.south east) -- (current page.south west)
			-- (current page.north west) -- (current page.north east);
		\addplot [data cs=polar, domain=0:90, samples=180, draw=none,
			fill = deepskyblue!40!white, fill opacity = 0.5,
			line width=1pt,	smooth](x, {sin(2*\x)});
	\end{scope}	

	% Outer curve
	\addplot [data cs=polar, domain=0:90, samples=180, rustred,
	line width=1pt, smooth](x, {sin(2*x)});
	\node[rustred] at (axis cs: 0.6,0.9) {$r=\sin(2\theta)$};

	% Inner curve
	\addplot [data cs=polar, domain=0:90, samples=180, deepskyblue,
	line width=1pt, smooth](x, {cos(x)});
	\node[deepskyblue] at (axis cs: 1.15,0.3) {$r=\cos(\theta)$};

	%Arrow
	\draw[->, very thick, orangepeel] (axis cs:0,0) -- (axis cs:{1.1*cos(45)},{1.1*sin(45)});

	\end{axis} 
	\end{tikzpicture}
